// Generates the two files an LLM reads instead of crawling the rendered site:
//
//   public/llms.txt        an index: every page, its URL and what it covers
//   public/llms-full.txt   every page's full Markdown, in reading order
//
// Both are regenerated by `npm run build` (see the prebuild script), so a page
// added under src/content/docs/ appears in them without anyone remembering to
// update a list.

import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { join, relative, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const CONTENT = join(here, "..", "src", "content", "docs");
const PUBLIC = join(here, "..", "public");
const SITE = "https://fang.copperhead.sh";

// The sidebar's order, so the files read the way the site does.
// The same order the sidebar reads in. `examples` is generated by
// generate-examples.mjs, which the prebuild runs first, so the pages are on
// disk by the time this walks them.
const SECTIONS = [
  { dir: "start", label: "Start here" },
  { dir: "concepts", label: "Concepts" },
  { dir: "examples", label: "Examples" },
  { dir: "reference", label: "Reference" },
];

async function walk(dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full)));
    else if (entry.name.endsWith(".md")) out.push(full);
  }
  return out;
}

// Front matter is title, description and an optional sidebar.order. A real YAML
// parser would be a dependency for three fields we control the shape of.
function parse(raw) {
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?/);
  if (!match) return { data: {}, body: raw.trim() };
  const data = {};
  const field = (name) => {
    const m = match[1].match(new RegExp(`^${name}:\\s*(.+)$`, "m"));
    return m ? m[1].trim().replace(/^["']|["']$/g, "") : undefined;
  };
  data.title = field("title");
  data.description = field("description");
  const order = match[1].match(/^\s+order:\s*(\d+)$/m);
  data.order = order ? Number(order[1]) : 99;
  return { data, body: raw.slice(match[0].length).trim() };
}

function urlFor(file) {
  const rel = relative(CONTENT, file).replace(/\\/g, "/").replace(/\.md$/, "");
  return rel === "index" ? `${SITE}/` : `${SITE}/${rel}/`;
}

const pages = [];
for (const file of await walk(CONTENT)) {
  const { data, body } = parse(await readFile(file, "utf8"));
  const rel = relative(CONTENT, file).replace(/\\/g, "/");
  pages.push({
    file: rel,
    section: rel.includes("/") ? rel.split("/")[0] : "",
    url: urlFor(file),
    title: data.title ?? rel,
    description: data.description ?? "",
    order: data.order,
    body,
  });
}

const home = pages.find((p) => p.file === "index.md");
const ordered = [];
if (home) ordered.push(home);
for (const { dir } of SECTIONS) {
  ordered.push(
    ...pages.filter((p) => p.section === dir).sort((a, b) => a.order - b.order)
  );
}

const SUMMARY =
  "Fang is a Python-embedded language for circuit boards and the typed kernel " +
  "that holds what you write. You author intent: typed interfaces, parameters " +
  "carrying units and constraints. The kernel elaborates that into one " +
  "canonical model, refuses anything it cannot justify and lowers what " +
  "survives into netlists, views, simulation decks and KiCad.";

const RULES = `The five rules that explain most of fang's behaviour, and the
mistakes to avoid when answering questions about it:

1. One canonical model. There is exactly one persisted representation of a
   design, the Engineering Intermediate Representation. A netlist, a view, a
   SPICE deck and a KiCad file are lowerings, projections or interchange
   encodings of it, never second stores. Constructing a second constraint
   registry raises ELAB-0012.
2. Undecided is a third truth value. An unknown operand makes a check
   undecided, never a quiet pass and never a quiet failure. Whether undecided
   blocks a commit is the gate's policy decision, not the evaluator's.
3. Unknown is a status, not a null. Value.unknown() is distinct from absent, and
   sources that disagree stay unresolved as a ConflictingValue.
4. Pin assignment is a lowering result, never an authoring input. Programs
   connect typed interfaces; the kernel decides which pads carry them and
   records a decision naming the alternatives it rejected.
5. Nothing is invented to fill a gap. A missing simulator reports unsupported, a
   missing model rejects the plan, an unrepresentable CAD construct is named in
   the import report and a generic part carries no manufacturer until one is
   selected.

Two things that are commonly got wrong. The PyPI distribution is
"copperhead-fang", not "fang", though the import name is fang. And the third
truth value is spelled Truth.UNDECIDED, while the check status for the same idea
is CheckStatus.UNKNOWN.`;

// ---- llms.txt: the index -------------------------------------------------
let index = `# fang\n\n> ${SUMMARY}\n\n${RULES}\n\n`;
index += `The full text of every page below is available in one file at
${SITE}/llms-full.txt.\n`;

if (home) index += `\n## Home\n\n- [${home.title}](${home.url}): ${home.description}\n`;
for (const { dir, label } of SECTIONS) {
  const inSection = ordered.filter((p) => p.section === dir);
  if (!inSection.length) continue;
  index += `\n## ${label}\n\n`;
  for (const p of inSection) {
    index += `- [${p.title}](${p.url})${p.description ? `: ${p.description}` : ""}\n`;
  }
}
index += `\n## Source of truth\n
The normative document is the specification at
https://github.com/copperheadhq/fang/blob/main/openspec/specs/fang-kernel/spec.md.
Where these pages and the spec disagree, the spec is right. The source is at
https://github.com/copperheadhq/fang.\n`;

// ---- llms-full.txt: every page -------------------------------------------
let full = `# fang: complete documentation\n\n> ${SUMMARY}\n\n${RULES}\n\n`;
full += `This file is every documentation page concatenated in reading order.
Generated from ${SITE}. Each page below names its own URL.\n`;
for (const p of ordered) {
  full += `\n\n---\n\n# ${p.title}\n\nURL: ${p.url}\n`;
  if (p.description) full += `Summary: ${p.description}\n`;
  full += `\n${p.body}\n`;
}

await mkdir(PUBLIC, { recursive: true });
await writeFile(join(PUBLIC, "llms.txt"), index, "utf8");
await writeFile(join(PUBLIC, "llms-full.txt"), full, "utf8");

const kb = (s) => `${(Buffer.byteLength(s, "utf8") / 1024).toFixed(1)} kB`;
console.log(
  `llms.txt (${ordered.length} pages, ${kb(index)}) and llms-full.txt (${kb(full)}) written`
);
